#ifndef TRESTDETECTORAVALANCHEPROCESS_H
#define TRESTDETECTORAVALANCHEPROCESS_H

#include <random>
#include <string>

#include "TRestEventProcess.h"

class TRestDetectorChargeResponse;

/// \class TRestDetectorAvalancheProcess
/// \brief Multiplies the drifted electrons of a TRestDetectorHitsEvent by the avalanche gain of the
/// amplification gap, from a gain table of the TRestDetectorMedium (TRestDetectorGainTable,
/// generated by restGarfield).
class TRestDetectorAvalancheProcess : public TRestEventProcess {
   private:
    const TRestDetectorChargeResponse* fCharge = nullptr;
    std::mt19937_64 fEngine;  //!

   public:
    /// Voltage across the amplification gap
    TRestWithUnits fAmplificationVoltage = 0;  // V
    /// Amplification gap (uniform field amplificationVoltage / gap)
    TRestWithUnits fGap = 0;  // mm
    /// Name of the TRestDetectorMedium. It can be omitted if the manager contains a single medium.
    std::string fMediumName = "";
    /// Key of the amplification table. Only needed if the medium has several with the gap
    std::string fTable = "";
    /// Seed of the random generator (0: random seed). Otherwise the generator is re-seeded at each event
    /// with TRestDetectorHitsEvent::EventSeed (seed, event and subevent IDs): independent of the threads.
    unsigned long fSeed = 0;

    /// Written with the values used (not inputs): mean gain and Polya parameter at the field
    double fGain = 0;
    double fTheta = 0;

    TRestDetectorAvalancheProcess();
    TRestDetectorAvalancheProcess(const std::string& instanceName, const YAML::Node& node);
    TRestDetectorAvalancheProcess(const std::string& fileName, const std::string& sectionName);

    void LoadConfig() override;
    void InitProcess() override;
    bool ProcessEvent(const TRestEvent& input, TRestEvent& output) override;
    void EndProcess() override {}

    std::string GetInputEvent() const override { return "TRestDetectorHitsEvent"; }
    std::string GetOutputEvent() const override { return "TRestDetectorHitsEvent"; }

    std::string GetClassName() const override { return "TRestDetectorAvalancheProcess"; }
};

#endif
